const data = JSON.parse($input.first().json.response);

function normalizeDate(date, meetingDate) {
  if (!date || date === "Invalid date") return "";

  if (/^\d{4}-\d{2}-\d{2}$/.test(date)) return date;

  const year = Number(meetingDate?.slice(0, 4)) || 2026;
  const clean = date.replace(/(\d+)(st|nd|rd|th)/gi, "$1");

  const parsed = new Date(`${clean}, ${year}`);

  if (isNaN(parsed.getTime())) return "";

  return [
    parsed.getFullYear(),
    String(parsed.getMonth() + 1).padStart(2, "0"),
    String(parsed.getDate()).padStart(2, "0")
  ].join("-");
}

return data.tasks.map(task => ({
  json: {
    task_name: task.task_name,
    assigned_to: task.assigned_to,
    due_date: normalizeDate(task.due_date, task.meeting_date),
    meeting_name: task.meeting_name,
    meeting_date: task.meeting_date
  }
}));

const response = JSON.parse($input.first().json.response);

const prd = response.prd_content;

if (!prd) {
  throw new Error("PRD content was not generated.");
}

const input = $("Edit Fields").first().json;

const project = input.project_name || "Project";
const meeting = input.meeting_name || "Meeting";
const date = input.meeting_date || "";

const safeName = (value) =>
  String(value).replace(/[\\/:*?"<>|]/g, "-").trim();

const filename = `${safeName(project)}_${safeName(meeting)}_${date}_vA`;

return [{
  json: {
    project_name: project,
    meeting_name: meeting,
    meeting_date: date,
    prd_title: filename,
    prd_content: prd,
    version: "vA",
    status: "Draft"
  }
}];
